<template><div class="space-y-6"><header><h1 class="text-2xl font-bold">Reports Center</h1><p class="text-sm text-gray-500">Reusable financial statements, spending, investment, debt, planning, and tax reports.</p></header><div class="grid gap-3 md:grid-cols-3"><div v-for="g in groups" :key="g.name" class="rounded-xl border bg-white p-4"><b>{{g.name}}</b><p class="mt-1 text-sm text-gray-500">{{g.items.join(' · ')}}</p></div></div><section class="rounded-xl border bg-white p-5"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="font-semibold">Financial Year in Review</h2><p class="text-sm text-gray-500">Deterministic synthesis from monthly aggregates and net-worth snapshots.</p></div><div><input v-model.number="startYear" min="2000" type="number" class="w-28 rounded-lg border-gray-300"><button class="ml-2 rounded-lg bg-indigo-600 px-4 py-2 text-white" @click="load">Generate</button><button v-if="review" class="ml-2 rounded-lg border px-4 py-2" @click="csv">CSV</button></div></div><div v-if="review" class="mt-5 space-y-4"><div class="grid gap-3 sm:grid-cols-4"><StatCard label="Income" :value="money(review.totalIncome)"/><StatCard label="Expenses" :value="money(review.totalExpenses)"/><StatCard label="Savings" :value="money(review.savings)"/><StatCard label="Net worth growth" :value="money(review.netWorthGrowth)"/></div><div class="grid gap-3 md:grid-cols-2"><div class="rounded-lg bg-green-50 p-4"><b>Biggest win</b><p class="text-sm">{{review.biggestWin}}</p></div><div class="rounded-lg bg-amber-50 p-4"><b>Priority</b><p class="text-sm">{{review.biggestWeakness}}</p></div></div><p class="text-sm">Top spending category: <b>{{review.topSpendingCategory}}</b> ({{money(review.topSpendingAmount)}})</p></div></section></div></template>
<script setup>import{ref}from'vue';import{reportsApi}from'../api/reports';import{formatMoney as money}from'../utils/formatters';import StatCard from'../components/StatCard.vue';const startYear=ref(new Date().getMonth()<3?new Date().getFullYear()-1:new Date().getFullYear()),review=ref(null);const groups=[{name:'Financial Statements',items:['Net Worth','Cash Flow','Assets & Liabilities']},{name:'Spending',items:['Category','Merchant','Budget vs Actual']},{name:'Investments',items:['Performance','Allocation','Capital Gains']},{name:'Debt',items:['Summary','Amortization','Interest Paid']},{name:'Planning',items:['Goals','Retirement','Protection']},{name:'Tax',items:['Projection','Readiness','Deductions']}];const load=async()=>review.value=(await reportsApi.fyReview(startYear.value)).data?.data;const csv=()=>{const rows=[['Metric','Value'],['Income',review.value.totalIncome],['Expenses',review.value.totalExpenses],['Savings',review.value.savings],['Net Worth Growth',review.value.netWorthGrowth]];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.map(x=>x.join(',')).join('\\n')],{type:'text/csv'}));a.download=`FinOS-FY-${review.value.financialYear}.csv`;a.click();URL.revokeObjectURL(a.href)}</script>
